    Check 'DS-08' {$plan=Get-OrcivoCodexModelPlan CRITICAL;Assert-True ($plan.ok -and $plan.model -eq 'gpt-5.6-terra' -and $plan.reasoning -eq 'high') 'HIGH did not pin Codex Plus Terra/high'}
