    Check 'DS-19' {$events=@([pscustomobject]@{type='item.completed';item=[pscustomobject]@{type='error';message='metadata warning'}},[pscustomobject]@{type='turn.completed';usage=[pscustomobject]@{input_tokens=12814;output_tokens=75}});$control=ConvertFrom-CodexEvents $events;Assert-True ($control -and -not $control.isError -and (Get-FailureClassV2 -Provider deepseek -ExitCode 0 -Control $control) -eq 'OK') 'real DeepSeek turn.completed stream was classified as incomplete'}
    Check 'DS-20' {$aggregate=@([pscustomobject]@{type='turn.completed';usage=[pscustomobject]@{input_tokens=12400984;output_tokens=59326;reasoning_output_tokens=16891}});$limit=Test-DeepSeekPerResponseOutputLimit -Events $aggregate -MaxOutputTokens 16000;Assert-True (-not $limit.exceeded) 'aggregate turn usage was incorrectly treated as a per-response cap violation';$single=@([pscustomobject]@{type='response.completed';response=[pscustomobject]@{usage=[pscustomobject]@{output_tokens=16001}}});Assert-True ((Test-DeepSeekPerResponseOutputLimit -Events $single -MaxOutputTokens 16000).exceeded) 'per-response cap violation was not detected'}
