        Assert-True ($first.classification -eq 'AGENT_INFRASTRUCTURE' -and $first.code -eq 'STRICT_STRUCTURED_OUTPUT_SCHEMA_REJECTED' -and $second.classification -eq 'AGENT_INFRASTRUCTURE' -and $second.code -eq 'STRICT_STRUCTURED_OUTPUT_SCHEMA_REJECTED' -and $null -eq $unrelated -and $null -eq $auth -and $null -eq $rate) 'strict schema diagnostics were over- or under-classified'
    }
