            $script:V2Dir=$localV2;$script:V2Config=Join-Path $localV2 'config.v2.json';$script:LedgerDir=Join-Path $localV2 'ledger';$script:DeepSeekBudgetDir=Join-Path $localV2 'budgets';$script:DispatcherRecoveryRunnerProbe=$false
