            $receipt=[ordered]@{schemaVersion='orcivo.orchestration.v2.agent-result-receipt/1';invocationId=$inv;provider='deepseek';model='deepseek-v4-flash';profile='FAST';reasoningIntent='low';attempt=2;exitCode=1;providerClass='PROVIDER_UNAVAILABLE';failureDiagnostic=$null;resultClass='AGENT_FAILURE';structuredResult=$null;promptArtifact=$prompt;promptHash=$promptHash;stdoutArtifact=$stdout;stdoutHash=$stdoutHash;stderrArtifact=$stderr;stderrHash=$stderrHash;controlRecordHash=$stdoutHash;duration=3;contextRolloverRequired=$false;capabilityVersion='fixture';continuationCheckpoint='';usage=$null;cachedTokens=$null;returnedModels=@();requestManifestPath=$requestPath;requestManifestHash=[string]$request.manifestHash;costUsd=$null;telemetryConsistent=$false;createdAt=(Get-Date).ToUniversalTime().ToString('o');receiptHash=''};$signed=[ordered]@{};foreach($k in $receipt.Keys){if($k -ne 'receiptHash'){$signed[$k]=$receipt[$k]}};$receipt.receiptHash=New-ContentHash $signed;$receiptPath=Join-Path $logs ($stem+'.agent-result.json');Write-TestJson $receiptPath $receipt
