            $auth='{"type":"error","message":"{\"error\":{\"message\":\"Authentication failed\",\"type\":\"authentication_error\"}}"}'+"`n"+'{"type":"turn.failed","error":{"message":"{\"error\":{\"message\":\"Authentication failed\",\"type\":\"authentication_error\"}}"}}'+"`n";$case=&$setEvidence $auth;Assert-True (-not(Test-DispatcherDeepSeekUnknownActiveReservation @case).eligible) 'authentication failure was reconciliation-eligible'
            $rate='{"type":"error","message":"{\"error\":{\"message\":\"Rate limit exceeded\",\"type\":\"rate_limit_error\"}}"}'+"`n"+'{"type":"turn.failed","error":{"message":"{\"error\":{\"message\":\"Rate limit exceeded\",\"type\":\"rate_limit_error\"}}"}}'+"`n";$case=&$setEvidence $rate;Assert-True (-not(Test-DispatcherDeepSeekUnknownActiveReservation @case).eligible) 'rate limit failure was reconciliation-eligible'
            $ambiguous=$raw+'{"type":"turn.failed","error":{"message":"{\"error\":{\"message\":\"Invalid json schema: duplicate failure evidence\",\"type\":\"invalid_request_error\"}}"}}'+"`n";$case=&$setEvidence $ambiguous;Assert-True (-not(Test-DispatcherDeepSeekUnknownActiveReservation @case).eligible) 'ambiguous duplicate turn.failed evidence was reconciliation-eligible'
