            $proofArgs=&$setEvidence $raw
            [IO.File]::AppendAllText($stdout,'tampered',(New-Object Text.UTF8Encoding($false)));Assert-True (-not(Test-DispatcherDeepSeekUnknownActiveReservation @proofArgs).eligible) 'stdout hash tampering was accepted';[IO.File]::WriteAllText($stdout,$raw,(New-Object Text.UTF8Encoding($false)))
