            $eligible=Test-DispatcherDeepSeekUnknownActiveReservation @proofArgs;Assert-True ($eligible.eligible -and [decimal]$eligible.reservation.maxUsd -eq 0.03) "exact unknown review reservation was not eligible: $($eligible.reason)"
            $historyBefore=ConvertTo-CanonicalJson $state.providerHistory;$first=Reconcile-DispatcherDeepSeekUnknownActiveReservation @proofArgs;$second=Reconcile-DispatcherDeepSeekUnknownActiveReservation @proofArgs;$after=Read-V2Json $budgetPath;$status=Get-DeepSeekBudgetStatus;$events=@((Read-JsonLines (Get-LedgerPath $tv))|Where-Object event -eq 'deepseek-unknown-reservation-reconciled')
            Assert-True ($first.status -eq 'RECONCILED_RESERVATION_CEILING' -and $second.status -eq 'ALREADY_RECONCILED' -and [decimal]$after.spentUsd -eq 0.03 -and [decimal]$after.invocations[0].costUsd -eq 0.03 -and $after.invocations[0].telemetryStatus -eq 'RECONCILED' -and $after.invocations[0].costAccuracy -eq 'RESERVATION_CEILING' -and $after.invocations[0].billingObservation -eq 'EXACT_PROVIDER_BILLING_UNOBSERVED' -and $after.reservations[0].status -eq 'RELEASED' -and $events.Count -eq 1 -and $status.ok -and (ConvertTo-CanonicalJson $state.providerHistory) -eq $historyBefore) "ceiling reconciliation mismatch first=$($first.status) second=$($second.status) spent=$($after.spentUsd) invocations=$(@($after.invocations).Count) cost=$($after.invocations[0].costUsd) telemetry=$($after.invocations[0].telemetryStatus) accuracy=$($after.invocations[0].costAccuracy) billing=$($after.invocations[0].billingObservation) reservation=$($after.reservations[0].status) events=$($events.Count) healthy=$($status.ok) history=$((ConvertTo-CanonicalJson $state.providerHistory) -eq $historyBefore) reason=$($status.reason) path=$($status.path) expected=$budgetPath"
            $reconciliationReceipt=Join-Path $localV2 "runs\$run\reconciliations\deepseek-$inv.unknown-reservation.json";[IO.File]::AppendAllText($reconciliationReceipt,'tampered',(New-Object Text.UTF8Encoding($false)));Assert-True (-not(Test-DispatcherDeepSeekUnknownActiveReservation @proofArgs).eligible) 'tampered reconciliation receipt was accepted'
        }finally{$script:V2Dir=$oldV2;$script:V2Config=$oldCfg;$script:LedgerDir=$oldLedger;$script:DeepSeekBudgetDir=$oldBudget;$script:DispatcherRecoveryRunnerProbe=$oldProbe}
    }
    Check 'DS-18' {
        $oldV2=$script:V2Dir;$oldCfg=$script:V2Config;$oldLedger=$script:LedgerDir;$oldRuntime=$script:DeepSeekRuntimePath;$oldBudget=$script:DeepSeekBudgetDir;$oldRegistry=$script:DeepSeekPriceRegistryPath;$oldProbe=$script:DispatcherRecoveryRunnerProbe
        try{
            $tv=('a'*64);$run='run-ds18-fixture';$inv=('att-'+('4'*32));$localV2=Join-Path $root 'v2';New-Item -ItemType Directory -Force -Path $localV2|Out-Null;Copy-Item (Join-Path (Get-RepoRoot) '.orchestration\v2\config.v2.json') (Join-Path $localV2 'config.v2.json')
            $script:V2Dir=$localV2;$script:V2Config=Join-Path $localV2 'config.v2.json';$script:LedgerDir=Join-Path $localV2 'ledger';$script:DeepSeekRuntimePath=$runtime;$script:DeepSeekBudgetDir=Join-Path $localV2 'budgets';$script:DeepSeekPriceRegistryPath=$registry;$script:DispatcherRecoveryRunnerProbe=$false
            $logs=Join-Path $localV2 "runs\$run\logs";New-Item -ItemType Directory -Force -Path $logs|Out-Null;$prompt=Join-Path $logs 'implementer-347-deepseek-44444444.prompt.txt';Write-TestJson $prompt 'prompt';$promptHash=New-FileHash $prompt;$request=New-DeepSeekRequestManifest -InvocationId $inv -PromptHash $promptHash -Model deepseek-v4-pro -Reasoning high -Profile REASONING;$requestPath=Join-Path $logs 'implementer-347-deepseek-44444444.request-manifest.json';Write-TestJson $requestPath $request;$stdout=Join-Path $logs 'implementer-347-deepseek-44444444.stdout.log';[IO.File]::WriteAllText($stdout,'{"type":"response.completed","response":{"usage":{"input_tokens":10,"output_tokens":2}}}' + "`n",(New-Object Text.UTF8Encoding($false)));$stdoutHash=New-FileHash $stdout
            $pre=[ordered]@{invocationId=$inv;attempt=347;provider='deepseek';model='deepseek-v4-pro';promptArtifact=$prompt;promptHash=$promptHash;snapshotHash='sha256:pre'};$post=[ordered]@{invocationId=$inv;attempt=347;preInvocationSnapshotHash='sha256:pre';stdoutHash=$stdoutHash;resultHash='sha256:post'};$state=[ordered]@{status='WAITING_PROVIDER';stage='IMPLEMENT';runId=$run;taskVersionId=$tv;providerHistory=@([ordered]@{invocationId=$inv;attempt=347;provider='deepseek';model='deepseek-v4-pro';exitCode=0;stdoutArtifact=$stdout;stdoutHash=$stdoutHash});workspaceInvocationSnapshots=@($pre);workspaceInvocationResultSnapshots=@($post);quarantineRetryRoute=[ordered]@{policy='CLEAN_QUARANTINED_RETRY_REQUIRES_FRESH_DEEPSEEK_PRO_HIGH';provider='deepseek';model='deepseek-v4-pro';profile='REASONING';reasoning='high'}}
            $budget=[ordered]@{schemaVersion='orcivo.orchestration.v2.deepseek-budget/1';month=(Get-Date).ToUniversalTime().ToString('yyyy-MM');spentUsd=0;invocations=@([ordered]@{invocationId=$inv;model='deepseek-v4-pro';costUsd=$null;telemetryStatus='UNKNOWN'});reservations=@([ordered]@{invocationId=$inv;model='deepseek-v4-pro';maxUsd=0.20;status='ACTIVE'})};$fixtureBudgetPath=Join-Path $localV2 'budgets\deepseek-fixture.json';Write-TestJson $fixtureBudgetPath $budget
            $fixtureBudget=Read-V2Json $fixtureBudgetPath;Assert-True (@($fixtureBudget.invocations|Where-Object{[string]$_.invocationId -eq $inv}).Count -eq 1) 'DS18 fixture invocation binding is absent';Assert-True (@($fixtureBudget.reservations|Where-Object{[string]$_.invocationId -eq $inv}).Count -eq 1) 'DS18 fixture reservation binding is absent'
            Initialize-LedgerTask -TaskVersionId $tv -Identity @{taskId='DS18'}|Out-Null;Add-LedgerEvent -TaskVersionId $tv -Event ready -ToState READY -RunId $run|Out-Null;Add-LedgerEvent -TaskVersionId $tv -Event 'provider-unavailable' -ToState WAITING_PROVIDER -RunId $run|Out-Null
            try{Reconcile-DispatcherDeepSeekUnknownReservation -State $state -TaskVersionId $tv -RunId $run -InvocationId $inv -ExpectedRequestManifestHash ('sha256:'+('0'*64)) -ExpectedStdoutHash $stdoutHash -ExpectedTailSeq 3 -BudgetPath $fixtureBudgetPath -V2Root $localV2;throw 'wrong request hash accepted'}catch{Assert-True ($_.Exception.Message -match 'hash') 'wrong request hash did not fail closed'}
            try{Reconcile-DispatcherDeepSeekUnknownReservation -State $state -TaskVersionId $tv -RunId $run -InvocationId $inv -ExpectedRequestManifestHash $request.manifestHash -ExpectedStdoutHash $stdoutHash -ExpectedTailSeq 4 -BudgetPath $fixtureBudgetPath -V2Root $localV2;throw 'wrong ledger tail accepted'}catch{Assert-True ($_.Exception.Message -match 'ledger tail') 'wrong ledger tail did not fail closed'}
            $first=Reconcile-DispatcherDeepSeekUnknownReservation -State $state -TaskVersionId $tv -RunId $run -InvocationId $inv -ExpectedRequestManifestHash $request.manifestHash -ExpectedStdoutHash $stdoutHash -ExpectedTailSeq 3 -BudgetPath $fixtureBudgetPath -V2Root $localV2;$second=Reconcile-DispatcherDeepSeekUnknownReservation -State $state -TaskVersionId $tv -RunId $run -InvocationId $inv -ExpectedRequestManifestHash $request.manifestHash -ExpectedStdoutHash $stdoutHash -ExpectedTailSeq 3 -BudgetPath $fixtureBudgetPath -V2Root $localV2;$after=Read-V2Json $fixtureBudgetPath;Assert-True ($first.status -eq 'RECONCILED_RESERVATION_CEILING' -and $second.status -eq 'ALREADY_RECONCILED' -and [decimal]$after.spentUsd -eq 0.20 -and [string]$after.reservations[0].status -eq 'RELEASED' -and (Get-LedgerState $tv).state -eq 'WAITING_PROVIDER') 'reservation ceiling reconciliation was not durable and idempotent'
            $receipt=Join-Path $localV2 "runs\$run\reconciliations\deepseek-$inv.reservation-ceiling.json";Add-Content -LiteralPath $receipt -Value 'tampered';try{Reconcile-DispatcherDeepSeekUnknownReservation -State $state -TaskVersionId $tv -RunId $run -InvocationId $inv -ExpectedRequestManifestHash $request.manifestHash -ExpectedStdoutHash $stdoutHash -ExpectedTailSeq 3 -BudgetPath $fixtureBudgetPath -V2Root $localV2;throw 'tampered receipt accepted'}catch{Assert-True ($_.Exception.Message -match 'receipt') 'tampered receipt did not fail closed'}
        }finally{$script:V2Dir=$oldV2;$script:V2Config=$oldCfg;$script:LedgerDir=$oldLedger;$script:DeepSeekRuntimePath=$oldRuntime;$script:DeepSeekBudgetDir=$oldBudget;$script:DeepSeekPriceRegistryPath=$oldRegistry;$script:DispatcherRecoveryRunnerProbe=$oldProbe}
    }
}finally{
    $results|ForEach-Object{Write-Output $_}
    $fails=@($results|Where-Object{$_ -match ' FAIL:'});Write-Output ("DEEPSEEK_TESTS: "+$(if($fails.Count){'FAIL'}else{'PASS'})+" ($($results.Count-$fails.Count)/$($results.Count) PASS)")
    if(Test-Path -LiteralPath $root){Remove-Item -LiteralPath $root -Recurse -Force}
}
if(@($results|Where-Object{$_ -match ' FAIL:'}).Count){exit 1}
